import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """DSATUR-style: distinct colours already used by a candidate's coloured neighbours, paired with its count of uncoloured neighbours."""
    k, c = neighbor_colors.shape
    if c == 0:
        sat = np.zeros(k, dtype=float)
    else:
        sat = (neighbor_colors > 0).sum(axis=1).astype(float)
        sat = sat / float(c)
    dyn = adjacency.sum(axis=1).astype(float) / max(float(k), 1.0)
    return np.stack([sat, dyn], axis=1)

import numpy as np


def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation degree (distinct colours among neighbours), with uncoloured degree as a bounded tie-break, scaled by colours used + 1."""
    nc = np.asarray(neighbor_colors)
    k = nc.shape[0]
    if k == 0:
        return np.zeros(0, dtype=float)

    if nc.shape[1] == 0:
        saturation = np.zeros(k, dtype=float)
        colours_used = 0
    else:
        saturation = np.count_nonzero(nc, axis=1).astype(float)
        colours_used = nc.shape[1]

    adj = np.asarray(adjacency, dtype=bool)
    if k > 1:
        uncoloured_degree = adj.sum(axis=1).astype(float)
    else:
        uncoloured_degree = np.zeros(k, dtype=float)

    # Degree fraction is in [0, 1), so it only resolves ties in saturation.
    tie_break = uncoloured_degree / float(max(k, 1))

    return (saturation + tie_break) / float(colours_used + 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Two columns: fraction of used colours present at a coloured neighbour, and degree normalised by the maximum candidate degree."""
    k = degree.shape[0]
    c = neighbor_colors.shape[1]
    if c == 0:
        sat = np.zeros(k, dtype=float)
    else:
        sat = (neighbor_colors > 0).sum(axis=1).astype(float) / float(c)
    max_deg = float(degree.max()) if k > 0 else 0.0
    deg = degree.astype(float) / max(1.0, max_deg)
    return np.column_stack((sat, deg))

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Fraction of a candidate's uncoloured neighbours that would claim the same first-fit colour it would take."""
    nc = np.asarray(neighbor_colors)
    k, c = nc.shape
    if k == 0:
        return np.zeros(0)

    # target colour = first existing colour absent from the candidate's neighbours, else a fresh colour (index c)
    if c == 0:
        target = np.zeros(k, dtype=np.int64)
    else:
        free = nc == 0
        any_free = free.any(axis=1)
        target = np.where(any_free, free.argmax(axis=1), c).astype(np.int64)

    # neighbours that would land on the very same colour -> direct competition for it
    same = (target[:, None] == target[None, :]) & adjacency
    counts = same.sum(axis=1).astype(float)

    uncol_deg = adjacency.sum(axis=1).astype(float)
    return counts / np.maximum(uncol_deg, 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """col1: fraction of used colours touching the candidate; col2: fraction of candidates sharing the candidate's first-fit colour (0 for new-colour openers)."""
    k, c = neighbor_colors.shape
    if k == 0:
        return np.zeros((0, 2))

    # col1: DSATUR-style saturation, normalised by colours used so far
    col1 = (neighbor_colors > 0).sum(axis=1).astype(float) / max(c, 1)

    # col2: how many candidates share this candidate's first-fit colour
    if c == 0:
        col2 = np.zeros(k)
    else:
        free = (neighbor_colors == 0)
        has_free = free.any(axis=1)
        j = np.where(has_free, free.argmax(axis=1), c)  # first free colour, or c
        counts = np.bincount(j, minlength=c + 1).astype(float)
        col2 = counts[j] / k
        col2[j == c] = 0.0  # new-colour openers carry no demand-group signal

    return np.stack([col1, col2], axis=1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Per candidate: fraction of used colours for which it is the only uncoloured vertex that can still take that colour."""
    k = neighbor_colors.shape[0]
    c = neighbor_colors.shape[1]
    if k == 0:
        return np.zeros((0,))
    if c == 0:
        return np.zeros((k,))
    free = (neighbor_colors == 0)          # (k, c) colours this candidate can take
    takers = free.sum(axis=0)              # (c,) how many candidates can take each colour
    sole = free & (takers[None, :] == 1)   # colours only this candidate can take
    return sole.sum(axis=1) / max(c, 1)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """For each candidate: its neighbour counts per used colour, weighted by 1/color_size, divided by its total degree."""
    k = degree.shape[0]
    if k == 0:
        return np.zeros((0,), dtype=float)

    c = color_sizes.shape[0]
    if c == 0:
        return np.zeros((k,), dtype=float)

    w = 1.0 / np.maximum(color_sizes.astype(float), 1.0)
    raw = neighbor_colors.astype(float) @ w
    return raw / np.maximum(degree.astype(float), 1.0)

import numpy as np


def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Per candidate: blocked colours weighted by remaining demand minus the plain count, and the demand of the colour the candidate would take (new colour demand = 1)."""
    k, c = neighbor_colors.shape
    if k == 0:
        return np.zeros((0, 2), dtype=np.float64)
    if c == 0:
        return np.column_stack([np.zeros(k, dtype=np.float64), np.ones(k, dtype=np.float64)])

    zero = (neighbor_colors == 0)
    demand_frac = zero.sum(axis=0).astype(np.float64) / max(k, 1)
    mean_d = float(demand_frac.mean())

    blocked = (neighbor_colors > 0).astype(np.float64)
    col1 = (blocked * (demand_frac - mean_d)[None, :]).sum(axis=1) / max(c, 1)

    has_takeable = zero.any(axis=1)
    ff = np.where(has_takeable, np.argmax(zero, axis=1), c)
    idx = np.minimum(ff, c - 1)
    col2 = np.where(ff < c, demand_frac[idx], 1.0)

    return np.column_stack([col1, col2])
